from collections import Counter
from contextlib import closing
import sqlite3
import uuid


def _validate_names(*names):
    if any(not isinstance(name, str) or not name for name in names):
        raise ValueError('invalid request')


def _account_balance(con, tenant, account):
    row = con.execute(
        'SELECT balance FROM accounts WHERE tenant = ? AND name = ?',
        (tenant, account),
    ).fetchone()
    if row is None or not isinstance(row[0], int):
        # Missing and inaccessible accounts deliberately have the same error.
        raise ValueError('invalid request')
    return row[0]


def _quote(name):
    return '"' + name.replace('"', '""') + '"'


def _sql_tokens(sql):
    """Locate SQL spans, leaving grammar validation to SQLite itself.

    SQLite's separators differ from Python's isspace(): VT is illegal, NBSP
    is an identifier character, and BOM is space only at a token boundary.
    Quoted text and comments must remain intact, including their semicolons.
    """
    index = 0
    while index < len(sql):
        start = index
        char = sql[index]
        if char in ' \t\r\n\f\ufeff':
            index += 1
            continue
        if sql.startswith('--', index):
            end = sql.find('\n', index + 2)
            index = len(sql) if end < 0 else end + 1
            continue
        if sql.startswith('/*', index):
            end = sql.find('*/', index + 2)
            index = len(sql) if end < 0 else end + 2
            continue
        if char in "'\"`[":
            close = ']' if char == '[' else char
            index += 1
            while index < len(sql):
                if sql[index] == close:
                    index += 1
                    if close != ']' and index < len(sql) and sql[index] == close:
                        index += 1
                        continue
                    break
                index += 1
        elif char.isascii() and (char.isalnum() or char in '_$') or ord(char) >= 128:
            index += 1
            while index < len(sql):
                char = sql[index]
                if not (char.isascii() and (char.isalnum() or char in '_$') or ord(char) >= 128):
                    break
                index += 1
        else:
            index += 1
        yield start, index, sql[start:index].upper()


def _instrument_trigger(con, sql, number, function, probe_name):
    tokens = list(_sql_tokens(sql))
    position = 2 if tokens[1][2] == 'TRIGGER' else 3
    if tokens[position][2] == 'IF':
        position += 3  # IF NOT EXISTS
    name_start, name_end, _ = tokens[position]
    position += 1
    if tokens[position][2] == '.':
        name_end = tokens[position + 1][1]
        position += 2
    if tokens[position][2] in ('BEFORE', 'AFTER'):
        position += 1
    elif tokens[position][2] == 'INSTEAD':
        position += 2
    event = tokens[position][2]
    tail = len(tokens) - 1
    while tokens[tail][2] == ';':
        tail -= 1
    guard = f"{function}('allowed', {number}, '{event}')"

    # BEGIN/WHEN can also be identifiers or occur inside CASE expressions.
    # Try preserved spans and let the installed engine choose a valid grammar,
    # rather than treating the first matching word as the trigger boundary.
    for begin in range(position + 1, tail):
        if tokens[begin][2] != 'BEGIN':
            continue
        cursor = tokens[begin][1]
        first = begin + 1
        body = []
        for end in range(begin + 1, tail):
            if tokens[end][2] != ';':
                continue
            operation = tokens[first][2]
            if operation not in ('INSERT', 'REPLACE', 'UPDATE', 'DELETE', 'SELECT'):
                break
            body.append(f"\nSELECT {function}('enter', {number}, '{operation}');\n")
            body.append(sql[cursor:tokens[end][1]])
            body.append(f"\nSELECT {function}('leave', {number}, '{operation}');\n")
            cursor = tokens[end][1]
            first = end + 1
        else:
            if not body:
                continue
            body.append(sql[cursor:])
            whens = [i for i in range(position + 1, begin) if tokens[i][2] == 'WHEN']
            for when in [*whens, None]:
                if when is None:
                    header = sql[:tokens[begin][0]] + 'WHEN ' + guard + '\n'
                else:
                    header = (sql[:tokens[when][0]] + 'WHEN ' + guard + ' AND ('
                              + sql[tokens[when][1]:tokens[begin][0]] + '\n) ')
                candidate = header + 'BEGIN' + ''.join(body)
                probe = candidate[:name_start] + _quote(probe_name) + candidate[name_end:]
                try:
                    con.execute('EXPLAIN ' + probe).fetchall()
                except sqlite3.Error:
                    continue
                return candidate
    raise sqlite3.IntegrityError('cannot observe storage effects')


class _TransferEffects:
    """Observe logical OLD/NEW deltas without selecting foreign stored rows.

    TEMP AFTER triggers see actual effects (including effects before a user's
    AFTER RAISE(IGNORE)). Recursive triggers expose implicit REPLACE deletions
    for every UNIQUE index. Existing triggers are guarded to retain SQLite's
    native nonrecursive behavior and its suppression of implicit DELETE
    triggers. All definition changes are restored within the transaction.
    Observer functions perform no SQL writes, preserving changes() and
    total_changes(). Rowids are deliberately not part of the logical frame.
    """

    def __init__(self, con):
        self.con = con
        self.delta = Counter()
        self.stack = []
        prefix = '_vault_' + uuid.uuid4().hex
        self.context = _quote(prefix + '_context')
        observe = _quote(prefix + '_observe')
        con.create_function(prefix + '_context', 3, self._context)
        con.create_function(prefix + '_observe', -1, self._observe)
        self.recursive = con.execute('PRAGMA recursive_triggers').fetchone()[0]
        self.originals = []
        if not self.recursive:
            self.originals = con.execute(
                "SELECT name, sql FROM main.sqlite_master WHERE type='trigger' ORDER BY rowid"
            ).fetchall()
            replacements = [_instrument_trigger(con, sql, index, self.context, prefix + '_probe')
                            for index, (_, sql) in enumerate(self.originals)]
            self._replace_triggers(replacements)
        con.execute('PRAGMA recursive_triggers=ON')
        columns = {'accounts': ('tenant', 'name', 'balance'),
                   'transfers': ('tenant', 'key', 'source', 'target', 'amount'),
                   'audit': ('tenant', 'key', 'source', 'target', 'amount')}
        for table, names in columns.items():
            for event, versions in (('INSERT', (('NEW', 1),)),
                                    ('DELETE', (('OLD', -1),)),
                                    ('UPDATE', (('OLD', -1), ('NEW', 1)))):
                statements = []
                for version, sign in versions:
                    args = []
                    for name in names:
                        value = version + '.' + _quote(name)
                        # Preserve storage classes and exact numbers; pass TEXT
                        # as bytes so even malformed foreign UTF-8 is opaque.
                        args.extend([f'typeof({value})', f"CASE WHEN typeof({value})='text' "
                                     f'THEN CAST({value} AS BLOB) ELSE {value} END'])
                    statements.append(f"SELECT {observe}('{table}', {sign}, {', '.join(args)});")
                con.execute(f'CREATE TEMP TRIGGER {_quote(prefix + table + event)} '
                            f'AFTER {event} ON main.{table} BEGIN {" ".join(statements)} END')

    def _replace_triggers(self, definitions):
        # Recreate in original order to preserve the order of sibling triggers.
        for name, _ in self.originals:
            self.con.execute('DROP TRIGGER main.' + _quote(name))
        for sql in definitions:
            self.con.execute(sql)

    def _context(self, action, number, operation):
        if action == 'allowed':
            return (not any(frame[0] == number for frame in self.stack)
                    and (operation != 'DELETE' or self.stack[-1][1] == 'DELETE'))
        if action == 'enter':
            self.stack.append((number, operation))
        else:
            for index in range(len(self.stack) - 1, 0, -1):
                if self.stack[index][0] == number:
                    # RAISE(IGNORE) can skip nested epilogues. The caller's
                    # statement boundary also discards those abandoned frames.
                    del self.stack[index:]
                    break

    def _observe(self, table, sign, *row):
        self.delta[(table, row)] += sign

    def execute(self, sql, values):
        self.stack = [(-1, sql.split()[0])]
        try:
            self.con.execute(sql, values)
        finally:
            self.stack.clear()

    def verify(self, tenant, source, target, funds, destination, amount, key):
        expected = Counter()

        def effect(table, sign, *values):
            row = tuple(part for value in values for part in
                        (('text', value.encode('utf-8')) if isinstance(value, str)
                         else ('integer', value)))
            expected[(table, row)] += sign

        effect('accounts', -1, tenant, source, funds)
        effect('accounts', 1, tenant, source, funds - amount)
        effect('accounts', -1, tenant, target, destination)
        effect('accounts', 1, tenant, target, destination + amount)
        for table in ('transfers', 'audit'):
            effect(table, 1, tenant, key, source, target, amount)
        if {row: n for row, n in self.delta.items() if n} != {row: n for row, n in expected.items() if n}:
            raise sqlite3.IntegrityError('unexpected storage effects')
        self._replace_triggers([sql for _, sql in self.originals])
        self.con.execute('PRAGMA recursive_triggers=' + str(self.recursive))


def init_db(path):
    with closing(sqlite3.connect(path, timeout=30)) as con:
        con.executescript('''
        CREATE TABLE IF NOT EXISTS accounts (
          tenant TEXT, name TEXT, balance INTEGER,
          PRIMARY KEY(tenant,name));
        CREATE TABLE IF NOT EXISTS transfers (
          tenant TEXT, key TEXT, source TEXT, target TEXT, amount INTEGER,
          PRIMARY KEY(tenant,key));
        CREATE TABLE IF NOT EXISTS audit (
          tenant TEXT, key TEXT, source TEXT, target TEXT, amount INTEGER);
        ''')


def balance(path, tenant, account):
    _validate_names(tenant, account)
    with closing(sqlite3.connect(path, timeout=30)) as con:
        return _account_balance(con, tenant, account)


def transfer(path, tenant, source, target, amount, key):
    _validate_names(tenant, source, target, key)
    if source == target or isinstance(amount, bool) or not isinstance(amount, int) or amount <= 0:
        raise ValueError('invalid request')

    receipt = dict(tenant=tenant, key=key, source=source, target=target, amount=amount)
    with closing(sqlite3.connect(path, timeout=30, isolation_level=None)) as con:
        con.row_factory = sqlite3.Row
        with con:
            # Serialize writers before reading either balances or replay keys.
            # A waiting request then sees the preceding transaction's commit.
            con.execute('BEGIN IMMEDIATE')
            old = con.execute(
                'SELECT tenant, key, source, target, amount FROM transfers '
                'WHERE tenant = ? AND key = ?', (tenant, key),
            ).fetchone()
            if old is not None:
                if dict(old) != receipt:
                    raise ValueError('invalid request')
                return dict(old)

            funds = _account_balance(con, tenant, source)
            destination = _account_balance(con, tenant, target)
            if funds < amount:
                raise ValueError('invalid request')

            effects = _TransferEffects(con)
            # Bind integer results: SQLite arithmetic otherwise converts an
            # overflowing integer credit into an inexact floating point value.
            effects.execute('UPDATE accounts SET balance = ? WHERE tenant = ? AND name = ?',
                            (funds - amount, tenant, source))
            effects.execute('UPDATE accounts SET balance = ? WHERE tenant = ? AND name = ?',
                            (destination + amount, tenant, target))
            values = (tenant, key, source, target, amount)
            effects.execute('INSERT INTO transfers (tenant, key, source, target, amount) '
                            'VALUES (?, ?, ?, ?, ?)', values)
            effects.execute('INSERT INTO audit (tenant, key, source, target, amount) '
                            'VALUES (?, ?, ?, ?, ?)', values)
            effects.verify(tenant, source, target, funds, destination, amount, key)
        # The context commits all four effects, or rolls them all back on error.
        return receipt
import json
import sqlite3
import sys

import vault


def _unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError('invalid request')
        result[key] = value
    return result


def main(argv=None):
    arguments = sys.argv[1:] if argv is None else argv
    try:
        if len(arguments) != 2:
            raise ValueError('invalid request')
        path, payload = arguments
        request = json.loads(payload, object_pairs_hook=_unique_object)
        if not isinstance(request, dict):
            raise ValueError('invalid request')
        operation = request.pop('op', None)
        if operation == 'balance':
            result = vault.balance(path, **request)
        elif operation == 'transfer':
            result = vault.transfer(path, **request)
        else:
            raise ValueError('invalid request')
    except (ValueError, TypeError, sqlite3.Error, OSError, OverflowError, RecursionError):
        print(json.dumps({'error': 'invalid request'}), file=sys.stderr)
        return 2
    print(json.dumps(result))
    return 0


if __name__ == '__main__':
    sys.exit(main())

from collections import Counter
from contextlib import closing
import json
from pathlib import Path
import sqlite3
import subprocess
import sys
import tempfile
import unittest

import vault


ROOT = Path(__file__).resolve().parent
COLUMNS = {
    'accounts': ('tenant', 'name', 'balance'),
    'transfers': ('tenant', 'key', 'source', 'target', 'amount'),
    'audit': ('tenant', 'key', 'source', 'target', 'amount'),
}


class FinalRepairTests(unittest.TestCase):
    def create_database(self, path, request, script, encoding):
        with closing(sqlite3.connect(path)) as con, con:
            # Persist the encoding before init_db creates the remaining tables.
            con.execute("PRAGMA encoding='" + encoding + "'")
            con.execute('CREATE TABLE accounts (tenant TEXT, name TEXT, balance INTEGER, '
                        'PRIMARY KEY(tenant,name))')
        vault.init_db(path)
        with closing(sqlite3.connect(path)) as con, con:
            self.assertEqual(con.execute('PRAGMA encoding').fetchone()[0], encoding)
            con.executemany('INSERT INTO accounts VALUES (?, ?, ?)', [
                (request['tenant'], request['source'], 100),
                (request['tenant'], request['target'], 0),
            ])
            con.execute("INSERT INTO accounts VALUES ('two', 'foreign', CAST(X'FF00FF' AS TEXT))")
            con.execute("INSERT INTO transfers VALUES ('two', 'history', 'old', 'target', 7)")
            con.executemany('INSERT INTO audit VALUES (?, ?, ?, ?, ?)',
                            [('two', 'history', 'old', 'target', 7)] * 2)
            con.executescript(script)

    def snapshot(self, path):
        with closing(sqlite3.connect(path)) as con:
            # Read raw database-encoding bytes, preserving malformed foreign
            # TEXT, storage classes, and duplicate historical rows.
            return {table: Counter(con.execute('SELECT ' + ', '.join(
                f"typeof({name}), CASE WHEN typeof({name})='text' "
                f'THEN CAST({name} AS BLOB) ELSE {name} END' for name in columns
            ) + ' FROM ' + table)) for table, columns in COLUMNS.items()}

    def schema(self, path):
        with closing(sqlite3.connect(path)) as con:
            return con.execute('SELECT type, name, sql FROM sqlite_master ORDER BY rowid').fetchall()

    def native_transfer(self, path, request):
        # Reference the four writes with SQLite's original trigger definitions
        # and default recursion semantics, on a fresh independent connection.
        with closing(sqlite3.connect(path)) as con, con:
            con.execute('PRAGMA recursive_triggers=OFF')
            con.execute('BEGIN IMMEDIATE')
            con.execute('UPDATE accounts SET balance=? WHERE tenant=? AND name=?',
                        (100 - request['amount'], request['tenant'], request['source']))
            con.execute('UPDATE accounts SET balance=? WHERE tenant=? AND name=?',
                        (request['amount'], request['tenant'], request['target']))
            values = tuple(request[name] for name in COLUMNS['transfers'])
            con.execute('INSERT INTO transfers VALUES (?, ?, ?, ?, ?)', values)
            con.execute('INSERT INTO audit VALUES (?, ?, ?, ?, ?)', values)

    def cli(self, path, request):
        return subprocess.run([sys.executable, '-B', str(ROOT / 'app.py'),
                               str(path), json.dumps(request)], cwd=ROOT,
                              capture_output=True, text=True, timeout=15)

    def assert_cli_success(self, result, expected):
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(result.stderr, '')
        self.assertEqual(len(result.stdout.splitlines()), 1)
        self.assertEqual(json.loads(result.stdout), expected)

    def assert_native_behavior(self, script, *, failure=None, encoding='UTF-8', request=None):
        if request is None:
            request = dict(tenant='one', source='a', target='b', amount=10, key='k')
        with tempfile.TemporaryDirectory(prefix='.final-repair-tests-', dir=ROOT) as directory:
            native = Path(directory) / 'native.sqlite'
            self.create_database(native, request, script, encoding)
            before, schema = self.snapshot(native), self.schema(native)
            if failure:
                with self.assertRaisesRegex(sqlite3.IntegrityError, failure):
                    self.native_transfer(native, request)
                self.assertEqual(self.snapshot(native), before)
            else:
                self.native_transfer(native, request)
            expected = self.snapshot(native)
            self.assertEqual(self.schema(native), schema)

            for interface in ('api', 'cli'):
                with self.subTest(interface=interface):
                    path = Path(directory) / (interface + '.sqlite')
                    self.create_database(path, request, script, encoding)
                    self.assertEqual(self.snapshot(path), before)
                    self.assertEqual(self.schema(path), schema)
                    if interface == 'api':
                        if failure:
                            with self.assertRaisesRegex(sqlite3.IntegrityError, failure):
                                vault.transfer(path, **request)
                        else:
                            self.assertEqual(vault.transfer(path, **request), request)
                    else:
                        result = self.cli(path, dict(op='transfer', **request))
                        if failure:
                            self.assertEqual(result.returncode, 2, result.stderr)
                            self.assertEqual(result.stdout, '')
                            self.assertEqual(result.stderr, '{"error": "invalid request"}\n')
                        else:
                            self.assert_cli_success(result, request)
                    self.assertEqual(self.snapshot(path), expected)
                    self.assertEqual(self.schema(path), schema)
                    if not failure:
                        # Reopen for exact replay and balances through both
                        # public interfaces; replay must add no storage effects.
                        self.assertEqual(vault.transfer(path, **request), request)
                        self.assert_cli_success(self.cli(path, dict(op='transfer', **request)), request)
                        self.assertEqual(self.snapshot(path), expected)
                        self.assertEqual(self.schema(path), schema)
                        self.assertEqual(vault.balance(path, request['tenant'], request['source']), 90)
                        self.assert_cli_success(self.cli(path, dict(
                            op='balance', tenant=request['tenant'], account=request['target'])), 10)

    def test_multirow_ignore_and_null_controls_preserve_abort_and_rollback(self):
        for timing in ('BEFORE', 'AFTER'):
            for expression in ('RAISE(IGNORE)', 'NULL'):
                with self.subTest(timing=timing, expression=expression):
                    self.assert_native_behavior(f"""
                        CREATE TRIGGER guard {timing} UPDATE ON accounts
                        WHEN NEW.balance=OLD.balance BEGIN
                          SELECT CASE WHEN NEW.name='a' THEN {expression}
                                 ELSE RAISE(ABORT, 'blocked') END;
                        END;
                        CREATE TRIGGER audit_check AFTER INSERT ON audit BEGIN
                          UPDATE accounts SET balance=balance WHERE tenant=NEW.tenant;
                        END;
                    """, failure='blocked')

    def test_conditional_ignore_preserves_recursive_guards_and_change_counters(self):
        for timing in ('BEFORE', 'AFTER'):
            for ignore in (True, False):
                expression = 'RaIsE /* preserve this span */ ( IgNoRe )' if ignore else 'NULL'
                total = (7 if timing == 'BEFORE' else 8) if ignore else 9
                changed = 1 if ignore and timing == 'BEFORE' else 2
                with self.subTest(timing=timing, ignore=ignore):
                    self.assert_native_behavior(f"""
                        CREATE TRIGGER guard {timing} UPDATE ON accounts
                        WHEN NEW.balance=OLD.balance BEGIN
                          UPDATE accounts SET balance=balance
                            WHERE tenant=NEW.tenant AND name=NEW.name;
                          SELECT 'RAISE(IGNORE); is text',
                                 CASE WHEN NEW.name='a' THEN {expression} END;
                          UPDATE accounts SET balance=balance
                            WHERE tenant=NEW.tenant AND name=NEW.name;
                        END;
                        CREATE TRIGGER audit_check AFTER INSERT ON audit BEGIN
                          UPDATE accounts SET balance=balance WHERE tenant=NEW.tenant;
                          SELECT CASE WHEN changes()!={changed} OR total_changes()!={total}
                                 THEN RAISE(ABORT, 'changed counter') END;
                        END;
                    """)

    def test_values_and_with_select_keep_native_trigger_behavior(self):
        statements = (
            'VALUES(1);',
            'WITH c AS (SELECT 1) SELECT * FROM c;',
            "VALUES('RAISE(IGNORE);'), ('quoted text');",
            'WITH RECURSIVE c(n) AS (VALUES(1) UNION ALL SELECT n+1 FROM c WHERE n<3) '
            'SELECT n FROM c;',
        )
        for statement in statements:
            with self.subTest(statement=statement):
                self.assert_native_behavior('CREATE TRIGGER t AFTER INSERT ON audit BEGIN '
                                            + statement + """
                    SELECT CASE WHEN changes()!=1 OR total_changes()!=3
                           THEN RAISE(ABORT, 'changed counter') END;
                    END;
                """)

    def test_delete_event_separators_and_identifiers_preserve_delete_semantics(self):
        boundaries = [('gate', ' \v'), ('gate', ' \ufeff'),
                      ('gate\u00a0name', ' '), ('gate\ufeffname', ' '), ('\u00a0gate', ' ')]
        for name, separator in boundaries:
            for explicit in (False, True):
                delete = ('DELETE FROM transfers WHERE tenant=NEW.tenant AND key=NEW.key;'
                          if explicit else '')
                with self.subTest(name=name, separator=separator, explicit=explicit):
                    self.assert_native_behavior(f"""
                        CREATE TRIGGER {name}{separator}DELETE ON transfers BEGIN
                          SELECT RAISE(ABORT, 'explicit deletion');
                        END;
                        CREATE TRIGGER replace_receipt AFTER INSERT ON audit BEGIN
                          {delete}
                          INSERT OR REPLACE INTO transfers VALUES
                            (NEW.tenant, NEW.key, NEW.source, NEW.target, NEW.amount);
                          SELECT CASE WHEN changes()!=1 OR total_changes()!=4
                                 THEN RAISE(ABORT, 'changed counter') END;
                        END;
                    """, failure='explicit deletion' if explicit else None)

    def test_database_encoding_preserves_unicode_and_raw_foreign_rows(self):
        request = dict(tenant='租户🗝', source="源'α", target='目β', amount=10, key='鍵☃🗝')
        for encoding in ('UTF-8', 'UTF-16le', 'UTF-16be'):
            with self.subTest(encoding=encoding):
                self.assert_native_behavior("""
                    CREATE TRIGGER keep_raw AFTER INSERT ON audit BEGIN
                      UPDATE accounts SET balance=balance WHERE tenant='two';
                      SELECT CASE WHEN changes()!=1 OR total_changes()!=4
                             THEN RAISE(ABORT, 'changed counter') END;
                    END;
                """, encoding=encoding, request=request)


if __name__ == '__main__':
    unittest.main()
